#!/usr/bin/env python3
"""Copy prototype/timeline.css (the single source of the styles) into the component packages.

    python3 tools/sync_css.py

web-component/src/timeline.css.js   the stylesheet as a JS string (the element needs no bundler)
react/src/timeline.css              the same file, imported by the React component
Do not edit the copies: they are overwritten.
"""
import json, pathlib

root = pathlib.Path(__file__).resolve().parent.parent
css = (root / 'prototype' / 'timeline.css').read_text()

(root / 'web-component' / 'src' / 'timeline.css.js').write_text(
    '// Generated by tools/sync_css.py from prototype/timeline.css. Do not edit.\n'
    'export default ' + json.dumps(css) + ';\n')
(root / 'react' / 'src' / 'timeline.css').write_text(css)
print('synced timeline.css into web-component/src and react/src')

# A classic-script build of the web component (no ES modules), so the demo pages also work from file://
import re
src = root / 'web-component' / 'src'
def body(name):
    t = (src / name).read_text()
    t = re.sub(r"^import .*?;\n", "", t, flags=re.M)
    return t
css_js = body('timeline.css.js').replace('export default ', 'const baseCss = ', 1)
views = body('views.js').replace('export const ', 'const ')
rail = body('timeline-rail.js').replace('export class TimelineRail', 'class TimelineRail', 1)
(root / 'web-component' / 'timeline-rail.bundle.js').write_text(
    '// Generated by tools/sync_css.py from web-component/src. Do not edit. Classic script; defines window.TimelineRail.\n'
    '( function () {\n' + css_js + '\n' + views + '\n' + rail + '\nwindow.TimelineRail = TimelineRail;\n} )();\n')
print('wrote web-component/timeline-rail.bundle.js')
